110	/// Keeps all user turns plus a bounded amount of recent assistant/tool context.
111	///
112	/// The pruning strategy is intentionally simple and reviewable:
113	/// - always retain user messages because they carry authorization and intent
114	/// - walk recent non-user entries from newest to oldest
115	/// - keep them only while the message/tool budgets allow
116	/// - reserve a separate tool budget so tool evidence cannot crowd out the human
117	///   conversation
118	///
119	/// User messages are never dropped unless the entire transcript must be omitted.
120	pub(crate) fn render_guardian_transcript_entries(
121	    entries: &[GuardianTranscriptEntry],
122	) -> (Vec<String>, Option<String>) {
123	    if entries.is_empty() {
124	        return (vec!["<no retained transcript entries>".to_string()], None);
125	    }
126	
127	    let rendered_entries = entries
128	        .iter()
129	        .enumerate()
130	        .map(|(index, entry)| {
131	            let token_cap = if entry.kind.is_tool() {
132	                GUARDIAN_MAX_TOOL_ENTRY_TOKENS
133	            } else {
134	                GUARDIAN_MAX_MESSAGE_ENTRY_TOKENS
135	            };
136	            let text = guardian_truncate_text(&entry.text, token_cap);
137	            let rendered = format!("[{}] {}: {}", index + 1, entry.kind.role(), text);
138	            let token_count = approx_token_count(&rendered);
139	            (rendered, token_count)
140	        })
141	        .collect::<Vec<_>>();
142	
143	    let mut included = vec![false; entries.len()];
144	    let mut message_tokens = 0usize;
145	    let mut tool_tokens = 0usize;
146	
147	    for (index, entry) in entries.iter().enumerate() {
148	        if !entry.kind.is_user() {
149	            continue;
150	        }
151	
152	        message_tokens += rendered_entries[index].1;
153	        if message_tokens > GUARDIAN_MAX_MESSAGE_TRANSCRIPT_TOKENS {
154	            return (
155	                vec!["<transcript omitted to preserve budget for planned action>".to_string()],
156	                Some("Conversation transcript omitted due to size.".to_string()),
157	            );
158	        }
159	        included[index] = true;
160	    }
161	
162	    let mut retained_non_user_entries = 0usize;
163	    for index in (0..entries.len()).rev() {
164	        let entry = &entries[index];
165	        if entry.kind.is_user() || retained_non_user_entries >= GUARDIAN_RECENT_ENTRY_LIMIT {
166	            continue;
167	        }
168	
169	        let token_count = rendered_entries[index].1;
170	        let within_budget = if entry.kind.is_tool() {
171	            tool_tokens + token_count <= GUARDIAN_MAX_TOOL_TRANSCRIPT_TOKENS
172	        } else {
173	            message_tokens + token_count <= GUARDIAN_MAX_MESSAGE_TRANSCRIPT_TOKENS
174	        };
175	        if !within_budget {
176	            continue;
177	        }
178	
179	        included[index] = true;
180	        retained_non_user_entries += 1;
181	        if entry.kind.is_tool() {
182	            tool_tokens += token_count;
183	        } else {
184	            message_tokens += token_count;
185	        }
186	    }
187	
188	    let transcript = entries
